INSERT OR IGNORE INTO cms_sections (id,page_id,section_key,section_type,display_name,sort_order,is_visible,draft_json,published_json,created_at,updated_at,published_at) VALUES ('home_profile', 'page_home', 'profile', 'form_and_text', 'لطلب عرض سعر', 40, 1, '{"eyebrow":"تواصل معنا","title":"لطلب عرض سعر","body":"نؤمن بأن تقديم حلول التموين والإعاشة المناسبة يسهم بشكل مباشر في رفع كفاءة القوى العاملة في مختلف المواقع والقطاعات. من مطابخنا المركزية، ترسل آلاف الوجبات يوميًا إلى أماكن العمل في جميع أنحاء المملكة، لتلبية احتياجات بيئات العمل المتنوعة مع الحفاظ على أعلى مستويات الجودة والالتزام الصارم بالعمليات التشغيلية.\n\nنعمل مع شركات رائدة ومشاريع كبرى في قطاعات الصناعة والبناء والضيافة والرعاية الصحية ومبادرات الرؤية، لنكون جزءًا لا يتجزأ من دورة تشغيلية تضمن استمرار القوى العاملة في تقديم أفضل أداء ممكن.\n\nيتمتع فريق نوهة بخبرة تشغيلية واسعة في إدارة خدمات التموين والإعاشة في بيئات عمل متنوعة، مع سجل حافل بالحفاظ على الجودة والانضباط التشغيلي.","buttonLabel":"إرسال وفتح واتساب","buttonUrl":""}', '{"eyebrow":"تواصل معنا","title":"لطلب عرض سعر","body":"نؤمن بأن تقديم حلول التموين والإعاشة المناسبة يسهم بشكل مباشر في رفع كفاءة القوى العاملة في مختلف المواقع والقطاعات. من مطابخنا المركزية، ترسل آلاف الوجبات يوميًا إلى أماكن العمل في جميع أنحاء المملكة، لتلبية احتياجات بيئات العمل المتنوعة مع الحفاظ على أعلى مستويات الجودة والالتزام الصارم بالعمليات التشغيلية.\n\nنعمل مع شركات رائدة ومشاريع كبرى في قطاعات الصناعة والبناء والضيافة والرعاية الصحية ومبادرات الرؤية، لنكون جزءًا لا يتجزأ من دورة تشغيلية تضمن استمرار القوى العاملة في تقديم أفضل أداء ممكن.\n\nيتمتع فريق نوهة بخبرة تشغيلية واسعة في إدارة خدمات التموين والإعاشة في بيئات عمل متنوعة، مع سجل حافل بالحفاظ على الجودة والانضباط التشغيلي.","buttonLabel":"إرسال وفتح واتساب","buttonUrl":""}', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now'));
UPDATE cms_sections SET section_type='form_and_text', display_name='لطلب عرض سعر', sort_order=40, draft_json=CASE WHEN draft_json='{}' THEN '{"eyebrow":"تواصل معنا","title":"لطلب عرض سعر","body":"نؤمن بأن تقديم حلول التموين والإعاشة المناسبة يسهم بشكل مباشر في رفع كفاءة القوى العاملة في مختلف المواقع والقطاعات. من مطابخنا المركزية، ترسل آلاف الوجبات يوميًا إلى أماكن العمل في جميع أنحاء المملكة، لتلبية احتياجات بيئات العمل المتنوعة مع الحفاظ على أعلى مستويات الجودة والالتزام الصارم بالعمليات التشغيلية.\n\nنعمل مع شركات رائدة ومشاريع كبرى في قطاعات الصناعة والبناء والضيافة والرعاية الصحية ومبادرات الرؤية، لنكون جزءًا لا يتجزأ من دورة تشغيلية تضمن استمرار القوى العاملة في تقديم أفضل أداء ممكن.\n\nيتمتع فريق نوهة بخبرة تشغيلية واسعة في إدارة خدمات التموين والإعاشة في بيئات عمل متنوعة، مع سجل حافل بالحفاظ على الجودة والانضباط التشغيلي.","buttonLabel":"إرسال وفتح واتساب","buttonUrl":""}' ELSE draft_json END, published_json=CASE WHEN published_json='{}' THEN '{"eyebrow":"تواصل معنا","title":"لطلب عرض سعر","body":"نؤمن بأن تقديم حلول التموين والإعاشة المناسبة يسهم بشكل مباشر في رفع كفاءة القوى العاملة في مختلف المواقع والقطاعات. من مطابخنا المركزية، ترسل آلاف الوجبات يوميًا إلى أماكن العمل في جميع أنحاء المملكة، لتلبية احتياجات بيئات العمل المتنوعة مع الحفاظ على أعلى مستويات الجودة والالتزام الصارم بالعمليات التشغيلية.\n\nنعمل مع شركات رائدة ومشاريع كبرى في قطاعات الصناعة والبناء والضيافة والرعاية الصحية ومبادرات الرؤية، لنكون جزءًا لا يتجزأ من دورة تشغيلية تضمن استمرار القوى العاملة في تقديم أفضل أداء ممكن.\n\nيتمتع فريق نوهة بخبرة تشغيلية واسعة في إدارة خدمات التموين والإعاشة في بيئات عمل متنوعة، مع سجل حافل بالحفاظ على الجودة والانضباط التشغيلي.","buttonLabel":"إرسال وفتح واتساب","buttonUrl":""}' ELSE published_json END, updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE page_id='page_home' AND section_key='profile';
