INSERT OR IGNORE INTO cms_sections (id,page_id,section_key,section_type,display_name,sort_order,is_visible,draft_json,published_json,created_at,updated_at,published_at) VALUES ('about_section_2', 'page_about', 'section_2', 'text_and_image', 'من احتياج تشغيل يومي إلى منظومة إعاشة متكاملة', 20, 1, '{"eyebrow":"قصة الشركة","title":"من احتياج تشغيل يومي إلى منظومة إعاشة متكاملة","body":"بدأت الشركة لتلبية احتياج المنشآت إلى شريك غذائي يعتمد عليه. هذا النص Placeholder يوضح مسار الشركة، خبرتها، نطاق عملها، وقدرتها على إدارة عقود متنوعة بأحجام مختلفة.\n\nيمكن لاحقًا استبدال هذا النص بتفاصيل التأسيس، المدن المخدومة، نوع العملاء، وحجم العمليات الفعلي.","imageUrl":"public/images/real/central-kitchen-hot-line-01.jpeg","imageAlt":"فريق عمل في مطبخ احترافي"}', '{"eyebrow":"قصة الشركة","title":"من احتياج تشغيل يومي إلى منظومة إعاشة متكاملة","body":"بدأت الشركة لتلبية احتياج المنشآت إلى شريك غذائي يعتمد عليه. هذا النص Placeholder يوضح مسار الشركة، خبرتها، نطاق عملها، وقدرتها على إدارة عقود متنوعة بأحجام مختلفة.\n\nيمكن لاحقًا استبدال هذا النص بتفاصيل التأسيس، المدن المخدومة، نوع العملاء، وحجم العمليات الفعلي.","imageUrl":"public/images/real/central-kitchen-hot-line-01.jpeg","imageAlt":"فريق عمل في مطبخ احترافي"}', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now'));
UPDATE cms_sections SET section_type='text_and_image', display_name='من احتياج تشغيل يومي إلى منظومة إعاشة متكاملة', sort_order=20, draft_json=CASE WHEN draft_json='{}' THEN '{"eyebrow":"قصة الشركة","title":"من احتياج تشغيل يومي إلى منظومة إعاشة متكاملة","body":"بدأت الشركة لتلبية احتياج المنشآت إلى شريك غذائي يعتمد عليه. هذا النص Placeholder يوضح مسار الشركة، خبرتها، نطاق عملها، وقدرتها على إدارة عقود متنوعة بأحجام مختلفة.\n\nيمكن لاحقًا استبدال هذا النص بتفاصيل التأسيس، المدن المخدومة، نوع العملاء، وحجم العمليات الفعلي.","imageUrl":"public/images/real/central-kitchen-hot-line-01.jpeg","imageAlt":"فريق عمل في مطبخ احترافي"}' ELSE draft_json END, published_json=CASE WHEN published_json='{}' THEN '{"eyebrow":"قصة الشركة","title":"من احتياج تشغيل يومي إلى منظومة إعاشة متكاملة","body":"بدأت الشركة لتلبية احتياج المنشآت إلى شريك غذائي يعتمد عليه. هذا النص Placeholder يوضح مسار الشركة، خبرتها، نطاق عملها، وقدرتها على إدارة عقود متنوعة بأحجام مختلفة.\n\nيمكن لاحقًا استبدال هذا النص بتفاصيل التأسيس، المدن المخدومة، نوع العملاء، وحجم العمليات الفعلي.","imageUrl":"public/images/real/central-kitchen-hot-line-01.jpeg","imageAlt":"فريق عمل في مطبخ احترافي"}' ELSE published_json END, updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE page_id='page_about' AND section_key='section_2';
INSERT OR IGNORE INTO cms_sections (id,page_id,section_key,section_type,display_name,sort_order,is_visible,draft_json,published_json,created_at,updated_at,published_at) VALUES ('about_section_3', 'page_about', 'section_3', 'cards', 'الرؤية', 30, 1, '{"title":"الرؤية","items":[{"text":"أن نكون شريكًا موثوقًا في حلول الإعاشة والتوريد الغذائي، مع نموذج تشغيل مرن يواكب توسع العملاء."},{"text":"تقديم وجبات وخدمات غذائية آمنة ومنظمة، مدعومة بفريق مؤهل وسلاسل توريد واضحة ومعايير جودة قابلة للقياس."}]}', '{"title":"الرؤية","items":[{"text":"أن نكون شريكًا موثوقًا في حلول الإعاشة والتوريد الغذائي، مع نموذج تشغيل مرن يواكب توسع العملاء."},{"text":"تقديم وجبات وخدمات غذائية آمنة ومنظمة، مدعومة بفريق مؤهل وسلاسل توريد واضحة ومعايير جودة قابلة للقياس."}]}', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now'));
