INSERT OR IGNORE INTO cms_sections (id,page_id,section_key,section_type,display_name,sort_order,is_visible,draft_json,published_json,created_at,updated_at,published_at) VALUES ('services_central-kitchens', 'page_services', 'central-kitchens', 'cards', 'نطاق الخدمة', 20, 1, '{"title":"نطاق الخدمة","body":"يمكن تخصيص هذه القائمة حسب القطاعات المستهدفة: مواقع عمالة، مستشفيات، مدارس، مصانع، فعاليات، أو مشاريع حكومية.","buttonLabel":"طلب استشارة","buttonUrl":"contact.html","items":[{"title":"الإعاشة الكاملة","text":"وجبات يومية متكاملة تشمل الإفطار والغداء والعشاء حسب خطة غذائية معتمدة."},{"title":"تشغيل المطابخ المركزية","text":"إدارة الطاقم، الجداول، التحضير، النظافة، ومراقبة الجودة داخل المطبخ."},{"title":"توريد الأغذية","text":"توريد مواد غذائية جافة ومبردة ومجمدة مع تنسيق التخزين والتسليم."},{"title":"تموين المواقع البعيدة","text":"حلول لوجستية للمشاريع خارج المدن مع خطط إمداد مستمرة."},{"title":"ضيافة الشركات","text":"تجهيز بوفيهات واجتماعات وضيافة يومية للمكاتب والمنشآت."},{"title":"إدارة المقاصف","text":"تشغيل نقاط بيع ومقاصف داخلية للمدارس والجامعات والمرافق."}]}', '{"title":"نطاق الخدمة","body":"يمكن تخصيص هذه القائمة حسب القطاعات المستهدفة: مواقع عمالة، مستشفيات، مدارس، مصانع، فعاليات، أو مشاريع حكومية.","buttonLabel":"طلب استشارة","buttonUrl":"contact.html","items":[{"title":"الإعاشة الكاملة","text":"وجبات يومية متكاملة تشمل الإفطار والغداء والعشاء حسب خطة غذائية معتمدة."},{"title":"تشغيل المطابخ المركزية","text":"إدارة الطاقم، الجداول، التحضير، النظافة، ومراقبة الجودة داخل المطبخ."},{"title":"توريد الأغذية","text":"توريد مواد غذائية جافة ومبردة ومجمدة مع تنسيق التخزين والتسليم."},{"title":"تموين المواقع البعيدة","text":"حلول لوجستية للمشاريع خارج المدن مع خطط إمداد مستمرة."},{"title":"ضيافة الشركات","text":"تجهيز بوفيهات واجتماعات وضيافة يومية للمكاتب والمنشآت."},{"title":"إدارة المقاصف","text":"تشغيل نقاط بيع ومقاصف داخلية للمدارس والجامعات والمرافق."}]}', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now'));
