INSERT OR IGNORE INTO cms_sections (id,page_id,section_key,section_type,display_name,sort_order,is_visible,draft_json,published_json,created_at,updated_at,published_at) VALUES ('certificates_section_2', 'page_certificates', 'section_2', 'image_cards', 'الشهادات والاعتمادات', 20, 1, '{"imageUrl":"public/Certificates/ethiopia-certificate.jpeg","imageAlt":"شهادة شكر وتقدير من مكتب شؤون حجاج إثيوبيا","items":[{"title":"شهادة شكر وتقدير من مكتب شؤون حجاج إثيوبيا","text":"شهادة شكر وتقدير مقدمة لشركة نوهة لخدمات الإعاشة نظير جهودها ومشاركتها في تقديم خدمات الإعاشة والتموين الغذائي خلال موسم حج 1447 هـ.","imageUrl":"public/Certificates/ethiopia-certificate.jpeg","imageAlt":"شهادة شكر وتقدير من مكتب شؤون حجاج إثيوبيا","linkUrl":"public/Certificates/ethiopia-certificate.jpeg"},{"title":"شهادة نظام HACCP لخدمات الإعاشة","text":"اعتماد HACCP لخدمات الإعاشة، يوضح التزام شركة نوهة بمعايير الجودة وسلامة الغذاء في التشغيل والتموين.","imageUrl":"public/Certificates/haccp-certificate.png","imageAlt":"شهادة نظام HACCP لخدمات الإعاشة","linkUrl":"public/Certificates/haccp-certificate.png"},{"title":"شهادة شكر من مكتب شؤون حجاج إندونيسيا - المدينة المنورة","text":"شهادة تقدير لمشاركة شركة نوهة في تجهيز خدمات حجاج إندونيسيا في المدينة المنورة لموسم 1446 هـ / 2025 م.","imageUrl":"public/Certificates/indonesia-certificate.png","imageAlt":"شهادة شكر من مكتب شؤون حجاج إندونيسيا - المدينة المنورة","linkUrl":"public/Certificates/indonesia-certificate.png"},{"title":"شهادة شكر وتقدير من مكتب شؤون حجاج إندونيسيا","text":"شهادة شكر عربية تقديرًا لجهود نوهة في الخدمات الإعاشية لحجاج إندونيسيا.","linkUrl":"public/Certificates/شهادات نوهة1 (1).pdf"},{"title":"شهادة شكر من مجموعة كاهايا المدينة الماليزية","text":"تقدير لتجهيز وتموين ضيوف الرحمن وحسن التعاون خلال موسم حج 1438 هـ / 2017 م.","linkUrl":"public/Certificates/شهادات نوهة1 (2).pdf"}]}', '{"imageUrl":"public/Certificates/ethiopia-certificate.jpeg","imageAlt":"شهادة شكر وتقدير من مكتب شؤون حجاج إثيوبيا","items":[{"title":"شهادة شكر وتقدير من مكتب شؤون حجاج إثيوبيا","text":"شهادة شكر وتقدير مقدمة لشركة نوهة لخدمات الإعاشة نظير جهودها ومشاركتها في تقديم خدمات الإعاشة والتموين الغذائي خلال موسم حج 1447 هـ.","imageUrl":"public/Certificates/ethiopia-certificate.jpeg","imageAlt":"شهادة شكر وتقدير من مكتب شؤون حجاج إثيوبيا","linkUrl":"public/Certificates/ethiopia-certificate.jpeg"},{"title":"شهادة نظام HACCP لخدمات الإعاشة","text":"اعتماد HACCP لخدمات الإعاشة، يوضح التزام شركة نوهة بمعايير الجودة وسلامة الغذاء في التشغيل والتموين.","imageUrl":"public/Certificates/haccp-certificate.png","imageAlt":"شهادة نظام HACCP لخدمات الإعاشة","linkUrl":"public/Certificates/haccp-certificate.png"},{"title":"شهادة شكر من مكتب شؤون حجاج إندونيسيا - المدينة المنورة","text":"شهادة تقدير لمشاركة شركة نوهة في تجهيز خدمات حجاج إندونيسيا في المدينة المنورة لموسم 1446 هـ / 2025 م.","imageUrl":"public/Certificates/indonesia-certificate.png","imageAlt":"شهادة شكر من مكتب شؤون حجاج إندونيسيا - المدينة المنورة","linkUrl":"public/Certificates/indonesia-certificate.png"},{"title":"شهادة شكر وتقدير من مكتب شؤون حجاج إندونيسيا","text":"شهادة شكر عربية تقديرًا لجهود نوهة في الخدمات الإعاشية لحجاج إندونيسيا.","linkUrl":"public/Certificates/شهادات نوهة1 (1).pdf"},{"title":"شهادة شكر من مجموعة كاهايا المدينة الماليزية","text":"تقدير لتجهيز وتموين ضيوف الرحمن وحسن التعاون خلال موسم حج 1438 هـ / 2017 م.","linkUrl":"public/Certificates/شهادات نوهة1 (2).pdf"}]}', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now'));
