INSERT OR IGNORE INTO cms_sections (id,page_id,section_key,section_type,display_name,sort_order,is_visible,draft_json,published_json,created_at,updated_at,published_at) VALUES ('company_profile_profile-document-section', 'page_company_profile', 'profile-document-section', 'text', 'ملف تعريفي مختصر يشرح قدرات نوهة التشغيلية', 20, 1, '{"eyebrow":"جاهز للعرض","title":"ملف تعريفي مختصر يشرح قدرات نوهة التشغيلية","body":"يعرض هذا الملف نموذج عمل نوهة في خدمات التموين والإعاشة، من تشغيل المطابخ المركزية وإعداد الوجبات اليومية إلى إدارة الإمداد والتوصيل وخدمة مواقع العمل في مختلف القطاعات.\n\nتم ترتيبه ليكون قريبًا من المرجع الذي أرسلته: زر واضح في الهيدر، صفحة تعريفية مباشرة، وإحصائيات مختصرة يمكن ربطها لاحقًا بملف PDF رسمي عند توفره.\n\nلا يوجد ملف PDF داخل المشروع حاليًا، لذلك تم تجهيز صفحة الملف التعريفي كرابط صحيح بدل رابط الشهادات السابق.","buttonLabel":"طلب نسخة الملف التعريفي","buttonUrl":"contact.html"}', '{"eyebrow":"جاهز للعرض","title":"ملف تعريفي مختصر يشرح قدرات نوهة التشغيلية","body":"يعرض هذا الملف نموذج عمل نوهة في خدمات التموين والإعاشة، من تشغيل المطابخ المركزية وإعداد الوجبات اليومية إلى إدارة الإمداد والتوصيل وخدمة مواقع العمل في مختلف القطاعات.\n\nتم ترتيبه ليكون قريبًا من المرجع الذي أرسلته: زر واضح في الهيدر، صفحة تعريفية مباشرة، وإحصائيات مختصرة يمكن ربطها لاحقًا بملف PDF رسمي عند توفره.\n\nلا يوجد ملف PDF داخل المشروع حاليًا، لذلك تم تجهيز صفحة الملف التعريفي كرابط صحيح بدل رابط الشهادات السابق.","buttonLabel":"طلب نسخة الملف التعريفي","buttonUrl":"contact.html"}', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now'));
