INSERT OR IGNORE INTO cms_sections (id,page_id,section_key,section_type,display_name,sort_order,is_visible,draft_json,published_json,created_at,updated_at,published_at) VALUES ('careers_section_2', 'page_careers', 'section_2', 'text_and_image', 'فريق يعتمد على الانضباط، سلامة الغذاء، وجودة الخدمة اليومية', 20, 1, '{"eyebrow":"بيئة العمل","title":"فريق يعتمد على الانضباط، سلامة الغذاء، وجودة الخدمة اليومية","body":"تحتاج مشاريع الإعاشة إلى فرق ملتزمة بالتفاصيل اليومية: التحضير، النظافة، الجداول، التوريد، والتعامل المهني مع مواقع العملاء. هذه الصفحة مخصصة لاستقبال طلبات الانضمام وفرزها مبدئيًا.\n\nيمكن لاحقًا ربط النموذج بالبريد الإلكتروني أو نظام موارد بشرية، وإضافة وظائف مفتوحة حسب المدينة والموقع.","imageUrl":"public/images/real/central-kitchen-hot-line-01.jpeg","imageAlt":"فريق عمل داخل مطبخ احترافي"}', '{"eyebrow":"بيئة العمل","title":"فريق يعتمد على الانضباط، سلامة الغذاء، وجودة الخدمة اليومية","body":"تحتاج مشاريع الإعاشة إلى فرق ملتزمة بالتفاصيل اليومية: التحضير، النظافة، الجداول، التوريد، والتعامل المهني مع مواقع العملاء. هذه الصفحة مخصصة لاستقبال طلبات الانضمام وفرزها مبدئيًا.\n\nيمكن لاحقًا ربط النموذج بالبريد الإلكتروني أو نظام موارد بشرية، وإضافة وظائف مفتوحة حسب المدينة والموقع.","imageUrl":"public/images/real/central-kitchen-hot-line-01.jpeg","imageAlt":"فريق عمل داخل مطبخ احترافي"}', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now'));
