INSERT OR IGNORE INTO cms_sections (id,page_id,section_key,section_type,display_name,sort_order,is_visible,draft_json,published_json,created_at,updated_at,published_at) VALUES ('central_kitchen_riyadh_kitchen-intro-section', 'page_central_kitchen_riyadh', 'kitchen-intro-section', 'text_and_image', 'نموذج الكفاءة في تقديم خدمات الإعاشة', 20, 1, '{"eyebrow":"المطبخ المركزي في الرياض","title":"نموذج الكفاءة في تقديم خدمات الإعاشة","body":"في ظل الطلب المتزايد على خدمات الإعاشة الجماعية عالية الجودة في مختلف قطاعات المملكة، تواصل نوهة التوسع بفعالية عبر تشغيل مطابخ مركزية مجهزة بالكامل.\n\nيقع المطبخ المركزي في الرياض في منطقة السلي، ويتميز بطاقة استيعابية وإنتاجية عالية، مع التزام صارم بمعايير الجودة وسلامة الغذاء.","imageUrl":"public/images/real/cold-storage-room-01.jpeg","imageAlt":"غرفة تخزين وتبريد داخل مطبخ مركزي"}', '{"eyebrow":"المطبخ المركزي في الرياض","title":"نموذج الكفاءة في تقديم خدمات الإعاشة","body":"في ظل الطلب المتزايد على خدمات الإعاشة الجماعية عالية الجودة في مختلف قطاعات المملكة، تواصل نوهة التوسع بفعالية عبر تشغيل مطابخ مركزية مجهزة بالكامل.\n\nيقع المطبخ المركزي في الرياض في منطقة السلي، ويتميز بطاقة استيعابية وإنتاجية عالية، مع التزام صارم بمعايير الجودة وسلامة الغذاء.","imageUrl":"public/images/real/cold-storage-room-01.jpeg","imageAlt":"غرفة تخزين وتبريد داخل مطبخ مركزي"}', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now'));
UPDATE cms_sections SET section_type='text_and_image', display_name='نموذج الكفاءة في تقديم خدمات الإعاشة', sort_order=20, draft_json=CASE WHEN draft_json='{}' THEN '{"eyebrow":"المطبخ المركزي في الرياض","title":"نموذج الكفاءة في تقديم خدمات الإعاشة","body":"في ظل الطلب المتزايد على خدمات الإعاشة الجماعية عالية الجودة في مختلف قطاعات المملكة، تواصل نوهة التوسع بفعالية عبر تشغيل مطابخ مركزية مجهزة بالكامل.\n\nيقع المطبخ المركزي في الرياض في منطقة السلي، ويتميز بطاقة استيعابية وإنتاجية عالية، مع التزام صارم بمعايير الجودة وسلامة الغذاء.","imageUrl":"public/images/real/cold-storage-room-01.jpeg","imageAlt":"غرفة تخزين وتبريد داخل مطبخ مركزي"}' ELSE draft_json END, published_json=CASE WHEN published_json='{}' THEN '{"eyebrow":"المطبخ المركزي في الرياض","title":"نموذج الكفاءة في تقديم خدمات الإعاشة","body":"في ظل الطلب المتزايد على خدمات الإعاشة الجماعية عالية الجودة في مختلف قطاعات المملكة، تواصل نوهة التوسع بفعالية عبر تشغيل مطابخ مركزية مجهزة بالكامل.\n\nيقع المطبخ المركزي في الرياض في منطقة السلي، ويتميز بطاقة استيعابية وإنتاجية عالية، مع التزام صارم بمعايير الجودة وسلامة الغذاء.","imageUrl":"public/images/real/cold-storage-room-01.jpeg","imageAlt":"غرفة تخزين وتبريد داخل مطبخ مركزي"}' ELSE published_json END, updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE page_id='page_central_kitchen_riyadh' AND section_key='kitchen-intro-section';
