INSERT OR IGNORE INTO cms_sections (id,page_id,section_key,section_type,display_name,sort_order,is_visible,draft_json,published_json,created_at,updated_at,published_at) VALUES ('central_kitchen_riyadh_section_4', 'page_central_kitchen_riyadh', 'section_4', 'cards', 'تصميم هندسي وتجهيزات عالمية', 40, 1, '{"eyebrow":"التجهيزات","title":"تصميم هندسي وتجهيزات عالمية","body":"تم تصميم مطبخ الرياض المركزي وفق أعلى المواصفات العالمية، ما يجعله قادرًا على الاستجابة بسرعة ومرونة للطلبات اليومية والموسمية.","items":[{"title":"خطوط إنتاج متعددة","text":"لتقليل وقت التحضير ورفع كفاءة التشغيل اليومي."},{"title":"أجهزة حديثة","text":"للطهي والتبريد والتغليف وفق متطلبات الإعاشة."},{"title":"أنظمة تهوية ومراقبة حرارة","text":"لضمان البيئة المثالية في مراحل التحضير والتجهيز."},{"title":"مسارات عمل مخصصة","text":"لفصل عمليات التحضير عن التعبئة والتسليم."}]}', '{"eyebrow":"التجهيزات","title":"تصميم هندسي وتجهيزات عالمية","body":"تم تصميم مطبخ الرياض المركزي وفق أعلى المواصفات العالمية، ما يجعله قادرًا على الاستجابة بسرعة ومرونة للطلبات اليومية والموسمية.","items":[{"title":"خطوط إنتاج متعددة","text":"لتقليل وقت التحضير ورفع كفاءة التشغيل اليومي."},{"title":"أجهزة حديثة","text":"للطهي والتبريد والتغليف وفق متطلبات الإعاشة."},{"title":"أنظمة تهوية ومراقبة حرارة","text":"لضمان البيئة المثالية في مراحل التحضير والتجهيز."},{"title":"مسارات عمل مخصصة","text":"لفصل عمليات التحضير عن التعبئة والتسليم."}]}', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now'));
