INSERT OR IGNORE INTO cms_sections (id,page_id,section_key,section_type,display_name,sort_order,is_visible,draft_json,published_json,created_at,updated_at,published_at) VALUES ('central_kitchen_riyadh_section_5', 'page_central_kitchen_riyadh', 'section_5', 'text', 'وجبات متوازنة بإشراف طهاة محترفين', 50, 1, '{"eyebrow":"الجودة الغذائية","title":"وجبات متوازنة بإشراف طهاة محترفين","body":"تعد وجباتنا تحت إشراف نخبة من الطهاة المحترفين ممن يتمتعون بخبرة واسعة في إعداد وجبات العمال ووجبات الموظفين وفق المعايير الصحية والغذائية العالمية.\n\nنأخذ في الاعتبار التنوع الثقافي في قوائم الطعام، مع الحرص على التوازن الغذائي والسعرات الحرارية. جميع مراحل الإعداد تتم وفق نظام HACCP لضمان سلامة الغذاء وجودة المخرجات."}', '{"eyebrow":"الجودة الغذائية","title":"وجبات متوازنة بإشراف طهاة محترفين","body":"تعد وجباتنا تحت إشراف نخبة من الطهاة المحترفين ممن يتمتعون بخبرة واسعة في إعداد وجبات العمال ووجبات الموظفين وفق المعايير الصحية والغذائية العالمية.\n\nنأخذ في الاعتبار التنوع الثقافي في قوائم الطعام، مع الحرص على التوازن الغذائي والسعرات الحرارية. جميع مراحل الإعداد تتم وفق نظام HACCP لضمان سلامة الغذاء وجودة المخرجات."}', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now'));
UPDATE cms_sections SET section_type='text', display_name='وجبات متوازنة بإشراف طهاة محترفين', sort_order=50, draft_json=CASE WHEN draft_json='{}' THEN '{"eyebrow":"الجودة الغذائية","title":"وجبات متوازنة بإشراف طهاة محترفين","body":"تعد وجباتنا تحت إشراف نخبة من الطهاة المحترفين ممن يتمتعون بخبرة واسعة في إعداد وجبات العمال ووجبات الموظفين وفق المعايير الصحية والغذائية العالمية.\n\nنأخذ في الاعتبار التنوع الثقافي في قوائم الطعام، مع الحرص على التوازن الغذائي والسعرات الحرارية. جميع مراحل الإعداد تتم وفق نظام HACCP لضمان سلامة الغذاء وجودة المخرجات."}' ELSE draft_json END, published_json=CASE WHEN published_json='{}' THEN '{"eyebrow":"الجودة الغذائية","title":"وجبات متوازنة بإشراف طهاة محترفين","body":"تعد وجباتنا تحت إشراف نخبة من الطهاة المحترفين ممن يتمتعون بخبرة واسعة في إعداد وجبات العمال ووجبات الموظفين وفق المعايير الصحية والغذائية العالمية.\n\nنأخذ في الاعتبار التنوع الثقافي في قوائم الطعام، مع الحرص على التوازن الغذائي والسعرات الحرارية. جميع مراحل الإعداد تتم وفق نظام HACCP لضمان سلامة الغذاء وجودة المخرجات."}' ELSE published_json END, updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE page_id='page_central_kitchen_riyadh' AND section_key='section_5';
