INSERT OR IGNORE INTO cms_sections (id,page_id,section_key,section_type,display_name,sort_order,is_visible,draft_json,published_json,created_at,updated_at,published_at) VALUES ('central_kitchen_madinah_kitchen-intro-section', 'page_central_kitchen_madinah', 'kitchen-intro-section', 'text_and_image', 'تشغيل يومي يخدم احتياج المواقع بكفاءة', 20, 1, '{"eyebrow":"المطبخ المركزي","title":"تشغيل يومي يخدم احتياج المواقع بكفاءة","body":"يمثل مطبخ المدينة المنورة نقطة التشغيل المركزية لدى نوهة، حيث يتم تجهيز الوجبات وفق مسارات عمل واضحة تشمل التخزين، التحضير، الطبخ، التغليف، والتسليم.\n\nيركز الفرع على خدمة المشاريع والمواقع التي تحتاج إلى جودة ثابتة واستجابة مرنة، مع مراعاة متطلبات السلامة الغذائية وسرعة التوزيع.","imageUrl":"public/images/real/cold-storage-room-01.jpeg","imageAlt":"غرفة تبريد وتخزين في المطبخ المركزي"}', '{"eyebrow":"المطبخ المركزي","title":"تشغيل يومي يخدم احتياج المواقع بكفاءة","body":"يمثل مطبخ المدينة المنورة نقطة التشغيل المركزية لدى نوهة، حيث يتم تجهيز الوجبات وفق مسارات عمل واضحة تشمل التخزين، التحضير، الطبخ، التغليف، والتسليم.\n\nيركز الفرع على خدمة المشاريع والمواقع التي تحتاج إلى جودة ثابتة واستجابة مرنة، مع مراعاة متطلبات السلامة الغذائية وسرعة التوزيع.","imageUrl":"public/images/real/cold-storage-room-01.jpeg","imageAlt":"غرفة تبريد وتخزين في المطبخ المركزي"}', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now'));
