INSERT OR IGNORE INTO cms_sections (id,page_id,section_key,section_type,display_name,sort_order,is_visible,draft_json,published_json,created_at,updated_at,published_at) VALUES ('central_kitchen_tabuk_duba_kitchen-intro-section', 'page_central_kitchen_tabuk_duba', 'kitchen-intro-section', 'text_and_image', 'دعم غذائي استراتيجي لمشاريع نيوم والمناطق المحيطة', 20, 1, '{"eyebrow":"المطبخ المركزي في تبوك ضباء","title":"دعم غذائي استراتيجي لمشاريع نيوم والمناطق المحيطة","body":"في قلب منطقة تبوك، وتحديدًا في مدينة ضباء، يقع أحد أهم مراكز عمليات نوهة للتموين والإعاشة. تم تأسيس هذا المطبخ ليكون محطة استراتيجية متقدمة تدعم مشاريع نيوم والمشاريع التنموية المحيطة بها.\n\nيعتمد مطبخ ضباء على أسطول من الشاحنات المبردة لضمان إيصال الوجبات في الوقت المحدد إلى مواقع العمل والمرافق السكنية ومقرات الشركات، مع أنظمة تتبع ومراقبة حرارية للحفاظ على جودة الطعام حتى لحظة التسليم.","imageUrl":"public/images/real/nooha-branded-delivery-truck-01.jpeg","imageAlt":"شاحنة نوهة المجهزة لخدمات التموين والتوصيل"}', '{"eyebrow":"المطبخ المركزي في تبوك ضباء","title":"دعم غذائي استراتيجي لمشاريع نيوم والمناطق المحيطة","body":"في قلب منطقة تبوك، وتحديدًا في مدينة ضباء، يقع أحد أهم مراكز عمليات نوهة للتموين والإعاشة. تم تأسيس هذا المطبخ ليكون محطة استراتيجية متقدمة تدعم مشاريع نيوم والمشاريع التنموية المحيطة بها.\n\nيعتمد مطبخ ضباء على أسطول من الشاحنات المبردة لضمان إيصال الوجبات في الوقت المحدد إلى مواقع العمل والمرافق السكنية ومقرات الشركات، مع أنظمة تتبع ومراقبة حرارية للحفاظ على جودة الطعام حتى لحظة التسليم.","imageUrl":"public/images/real/nooha-branded-delivery-truck-01.jpeg","imageAlt":"شاحنة نوهة المجهزة لخدمات التموين والتوصيل"}', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now'));
