INSERT OR IGNORE INTO cms_sections (id,page_id,section_key,section_type,display_name,sort_order,is_visible,draft_json,published_json,created_at,updated_at,published_at) VALUES ('central_kitchen_tabuk_duba_kitchen-capacity', 'page_central_kitchen_tabuk_duba', 'kitchen-capacity', 'metrics', 'طاقة تشغيلية عالية وموقع استراتيجي', 30, 1, '{"eyebrow":"موقع استراتيجي","title":"طاقة تشغيلية عالية وموقع استراتيجي","body":"تم اختيار الموقع بعناية ليكون قريبًا من مواقع المشاريع الكبرى، مما يقلل زمن التوصيل ويزيد من كفاءة سلسلة الإمداد الغذائي، خصوصًا في مشاريع تتطلب استجابة فورية وسعة إنتاج ضخمة.","items":[{"title":"1,500"},{"title":"12,000"},{"title":"4,000"}]}', '{"eyebrow":"موقع استراتيجي","title":"طاقة تشغيلية عالية وموقع استراتيجي","body":"تم اختيار الموقع بعناية ليكون قريبًا من مواقع المشاريع الكبرى، مما يقلل زمن التوصيل ويزيد من كفاءة سلسلة الإمداد الغذائي، خصوصًا في مشاريع تتطلب استجابة فورية وسعة إنتاج ضخمة.","items":[{"title":"1,500"},{"title":"12,000"},{"title":"4,000"}]}', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now'));
