INSERT OR IGNORE INTO cms_sections (id,page_id,section_key,section_type,display_name,sort_order,is_visible,draft_json,published_json,created_at,updated_at,published_at) VALUES ('central_kitchen_tabuk_duba_section_4', 'page_central_kitchen_tabuk_duba', 'section_4', 'cards', 'خدمة تموين متكاملة لمشاريع نيوم', 40, 1, '{"eyebrow":"نطاق الخدمة","title":"خدمة تموين متكاملة لمشاريع نيوم","body":"من خلال مطبخ ضباء، تقدم نوهة خدمات تموين يومية لعدد من المشاريع الحيوية، ضمن أنظمة غذائية متوازنة وتحت إشراف طهاة محترفين وفريق جودة وسلامة متخصص.","items":[{"title":"شركات المقاولات","text":"العاملة في مشاريع نيوم ومواقع الإنشاء."},{"title":"معسكرات العمال","text":"في مواقع الإنشاء والتطوير والمرافق السكنية."},{"title":"المرافق الإدارية","text":"والخدمية التي تحتاج إلى وجبات منتظمة."},{"title":"الفنادق المؤقتة","text":"ومساكن الموظفين داخل نطاق المشاريع."},{"title":"مشاريع البنية التحتية","text":"والمرافق الصناعية ذات التشغيل اليومي."}]}', '{"eyebrow":"نطاق الخدمة","title":"خدمة تموين متكاملة لمشاريع نيوم","body":"من خلال مطبخ ضباء، تقدم نوهة خدمات تموين يومية لعدد من المشاريع الحيوية، ضمن أنظمة غذائية متوازنة وتحت إشراف طهاة محترفين وفريق جودة وسلامة متخصص.","items":[{"title":"شركات المقاولات","text":"العاملة في مشاريع نيوم ومواقع الإنشاء."},{"title":"معسكرات العمال","text":"في مواقع الإنشاء والتطوير والمرافق السكنية."},{"title":"المرافق الإدارية","text":"والخدمية التي تحتاج إلى وجبات منتظمة."},{"title":"الفنادق المؤقتة","text":"ومساكن الموظفين داخل نطاق المشاريع."},{"title":"مشاريع البنية التحتية","text":"والمرافق الصناعية ذات التشغيل اليومي."}]}', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now'));
