INSERT OR IGNORE INTO cms_sections (id,page_id,section_key,section_type,display_name,sort_order,is_visible,draft_json,published_json,created_at,updated_at,published_at) VALUES ('makkah_branch_kitchen-intro-section', 'page_makkah_branch', 'kitchen-intro-section', 'text_and_image', 'خدمة قريبة من مواقع التشغيل', 20, 1, '{"eyebrow":"فرع مكة","title":"خدمة قريبة من مواقع التشغيل","body":"يدعم فرع مكة أعمال التموين للمواقع التي تحتاج إلى سرعة استجابة وتنظيم في تجهيز الطلبات، خصوصًا في المواسم وفترات كثافة الطلب.\n\nيركز الفرع على تنسيق الطلبات اليومية، متابعة الاحتياج، وتجهيز نموذج خدمة يناسب طبيعة الموقع وعدد المستفيدين.","imageUrl":"public/images/real/delivery-preparation-01.jpeg","imageAlt":"تجهيز طلبات التموين في فرع مكة"}', '{"eyebrow":"فرع مكة","title":"خدمة قريبة من مواقع التشغيل","body":"يدعم فرع مكة أعمال التموين للمواقع التي تحتاج إلى سرعة استجابة وتنظيم في تجهيز الطلبات، خصوصًا في المواسم وفترات كثافة الطلب.\n\nيركز الفرع على تنسيق الطلبات اليومية، متابعة الاحتياج، وتجهيز نموذج خدمة يناسب طبيعة الموقع وعدد المستفيدين.","imageUrl":"public/images/real/delivery-preparation-01.jpeg","imageAlt":"تجهيز طلبات التموين في فرع مكة"}', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now'));
UPDATE cms_sections SET section_type='text_and_image', display_name='خدمة قريبة من مواقع التشغيل', sort_order=20, draft_json=CASE WHEN draft_json='{}' THEN '{"eyebrow":"فرع مكة","title":"خدمة قريبة من مواقع التشغيل","body":"يدعم فرع مكة أعمال التموين للمواقع التي تحتاج إلى سرعة استجابة وتنظيم في تجهيز الطلبات، خصوصًا في المواسم وفترات كثافة الطلب.\n\nيركز الفرع على تنسيق الطلبات اليومية، متابعة الاحتياج، وتجهيز نموذج خدمة يناسب طبيعة الموقع وعدد المستفيدين.","imageUrl":"public/images/real/delivery-preparation-01.jpeg","imageAlt":"تجهيز طلبات التموين في فرع مكة"}' ELSE draft_json END, published_json=CASE WHEN published_json='{}' THEN '{"eyebrow":"فرع مكة","title":"خدمة قريبة من مواقع التشغيل","body":"يدعم فرع مكة أعمال التموين للمواقع التي تحتاج إلى سرعة استجابة وتنظيم في تجهيز الطلبات، خصوصًا في المواسم وفترات كثافة الطلب.\n\nيركز الفرع على تنسيق الطلبات اليومية، متابعة الاحتياج، وتجهيز نموذج خدمة يناسب طبيعة الموقع وعدد المستفيدين.","imageUrl":"public/images/real/delivery-preparation-01.jpeg","imageAlt":"تجهيز طلبات التموين في فرع مكة"}' ELSE published_json END, updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE page_id='page_makkah_branch' AND section_key='kitchen-intro-section';
