INSERT OR IGNORE INTO cms_sections (id,page_id,section_key,section_type,display_name,sort_order,is_visible,draft_json,published_json,created_at,updated_at,published_at) VALUES ('riyadh_import_export_kitchen-intro-section', 'page_riyadh_import_export', 'kitchen-intro-section', 'text_and_image', 'دعم لوجستي وسلاسل إمداد منظمة', 20, 1, '{"eyebrow":"الاستيراد والتصدير","title":"دعم لوجستي وسلاسل إمداد منظمة","body":"يدعم فرع المدينة المنورة أعمال الاستيراد والتصدير والتوريد، بما يساعد على توفير المواد والاحتياجات التشغيلية لخدمات التموين والإعاشة.\n\nيعزز الفرع قدرة نوهة على تنسيق الإمداد، متابعة الموردين، وخدمة المواقع عبر نموذج تشغيل واضح وقابل للتوسع.","imageUrl":"public/images/real/nooha-branded-delivery-truck-01.jpeg","imageAlt":"شاحنة نوهة لخدمات النقل والإمداد"}', '{"eyebrow":"الاستيراد والتصدير","title":"دعم لوجستي وسلاسل إمداد منظمة","body":"يدعم فرع المدينة المنورة أعمال الاستيراد والتصدير والتوريد، بما يساعد على توفير المواد والاحتياجات التشغيلية لخدمات التموين والإعاشة.\n\nيعزز الفرع قدرة نوهة على تنسيق الإمداد، متابعة الموردين، وخدمة المواقع عبر نموذج تشغيل واضح وقابل للتوسع.","imageUrl":"public/images/real/nooha-branded-delivery-truck-01.jpeg","imageAlt":"شاحنة نوهة لخدمات النقل والإمداد"}', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now'));
UPDATE cms_sections SET section_type='text_and_image', display_name='دعم لوجستي وسلاسل إمداد منظمة', sort_order=20, draft_json=CASE WHEN draft_json='{}' THEN '{"eyebrow":"الاستيراد والتصدير","title":"دعم لوجستي وسلاسل إمداد منظمة","body":"يدعم فرع المدينة المنورة أعمال الاستيراد والتصدير والتوريد، بما يساعد على توفير المواد والاحتياجات التشغيلية لخدمات التموين والإعاشة.\n\nيعزز الفرع قدرة نوهة على تنسيق الإمداد، متابعة الموردين، وخدمة المواقع عبر نموذج تشغيل واضح وقابل للتوسع.","imageUrl":"public/images/real/nooha-branded-delivery-truck-01.jpeg","imageAlt":"شاحنة نوهة لخدمات النقل والإمداد"}' ELSE draft_json END, published_json=CASE WHEN published_json='{}' THEN '{"eyebrow":"الاستيراد والتصدير","title":"دعم لوجستي وسلاسل إمداد منظمة","body":"يدعم فرع المدينة المنورة أعمال الاستيراد والتصدير والتوريد، بما يساعد على توفير المواد والاحتياجات التشغيلية لخدمات التموين والإعاشة.\n\nيعزز الفرع قدرة نوهة على تنسيق الإمداد، متابعة الموردين، وخدمة المواقع عبر نموذج تشغيل واضح وقابل للتوسع.","imageUrl":"public/images/real/nooha-branded-delivery-truck-01.jpeg","imageAlt":"شاحنة نوهة لخدمات النقل والإمداد"}' ELSE published_json END, updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE page_id='page_riyadh_import_export' AND section_key='kitchen-intro-section';
